/**
 * @synova/engine-core task-store — 桥接到 Novis 服务端的 SQLite task-store
 *
 * 本模块是 engine-core 与 Novis 服务端的桥接层。
 * engine-core 的编排器（orchestrator）通过本模块更新管线进度；
 * 实际数据写入 Novis 服务端的 SQLite task-store（server/src/engine-server/task-store.ts）。
 *
 * 如果桥接不可用（如单元测试、独立运行），自动回退到 in-memory Map。
 */
export declare function getOrCreateTask(request: any, taskId?: string): any;
export declare function getTaskStatus(taskId: string): any;
export declare function getTaskRecord(taskId: string): any;
export declare function getBlueprintRecord(blueprintId: string): any;
export declare function updateTaskProgress(taskId: string, data: any, _message?: string): void;
export declare function updateTaskStatus(taskId: string, status: any, message?: string): void;
export declare function markCompleted(taskId: string, result: any): void;
export declare function markFailed(taskId: string, error: any): void;
export declare function listCompletedBlueprints(): any[];
